EXPLAIN (ANALYZE, COSTS OFF, SUMMARY ON, TIMING ON) SELECT t.*, q.pickup_latitude, q.pickup_longitude, q.dropoff_latitude, q.dropoff_longitude, q.amount_minor, (SELECT jsonb_agg(jsonb_build_object('id', p.id, 'purpose', p.purpose, 'status', p.status, 'amount_minor', p.amount_minor, 'currency', p.currency)) FROM payment p WHERE p.trip_id = t.id) FROM trip t JOIN fare_quote q ON q.id = t.fare_quote_id WHERE t.id = '40000000-0000-0000-0000-000000198904' AND t.rider_id = '10000000-0000-0000-0000-000000000777';
EXPLAIN (ANALYZE, COSTS OFF, SUMMARY ON, TIMING ON) SELECT t.*, q.pickup_latitude, q.pickup_longitude, q.dropoff_latitude, q.dropoff_longitude, q.amount_minor, (SELECT jsonb_agg(jsonb_build_object('id', p.id, 'purpose', p.purpose, 'status', p.status, 'amount_minor', p.amount_minor, 'currency', p.currency)) FROM payment p WHERE p.trip_id = t.id) FROM trip t JOIN fare_quote q ON q.id = t.fare_quote_id WHERE t.id = '40000000-0000-0000-0000-000000198904' AND t.rider_id = '10000000-0000-0000-0000-000000000777';
\echo '=== E2 EP03 full read, two other trips (any rider), 3 runs each'
EXPLAIN (ANALYZE, COSTS OFF, SUMMARY ON) SELECT t.*, q.amount_minor, (SELECT jsonb_agg(jsonb_build_object('id', p.id, 'status', p.status)) FROM payment p WHERE p.trip_id = t.id) FROM trip t JOIN fare_quote q ON q.id = t.fare_quote_id WHERE t.id = '40000000-0000-0000-0000-000000111893';
